  always @(posedge pclk or negedge presetn)
  begin
      if (!presetn) begin
          passwd  <= 32'h0badbeef;
      end 
      else if (hwr_PASSWORD) begin
          passwd  <= pwdata[31:0];
      end
  end
        
reg                  parity_err_status;                          
  always @(posedge pclk or negedge presetn)
  begin
      if (!presetn) begin
          parity_err_status  <= 1'b0;
      end
      else if (reg_parity_error) begin
          parity_err_status  <= 1'b1;
      end
      else if (hwr_MIssionIntStatusSet0 & pwdata[0]) begin
          parity_err_status  <= 1'b1;
      end
      else if (hwr_MIssionIntStatus0) begin
          if (pwdata[0] == 1'b1) begin
              parity_err_status  <= ~pwdata[0];
          end
      end
  end
        
  always @(posedge pclk or negedge presetn)
  begin
      if (!presetn) begin
          parity_invert_d <= 1'b0;
      end

      else
          parity_invert_d <= parity_invert;
      end

  always @(posedge pclk or negedge presetn)
  begin
      if (!presetn) begin
          parity_invert_d2 <= 1'b0;
      end

      else
          parity_invert_d2 <= parity_invert_d;
      end

   assign parity_invert_posedge = parity_invert & (~parity_invert_d);
   assign parity_invert_d_posedge = parity_invert_d & (~parity_invert_d2);
   assign parity_invert_2cycle = parity_invert_posedge | parity_invert_d_posedge;
            
